// Parse and personalize WhatsApp message
const items = $input.all();
const messages = [];

for (const item of items) {
  const body = item.json.body || item.json;

  // Message templates by type
  const templates = {
    installer_notification: (data) => `
🔔 *Novo Lead Qualificado - AvaliaSolar*

👤 *Nome:* ${data.lead_name}
📧 *Email:* ${data.lead_email}
📱 *Telefone:* ${data.lead_phone}
🏙️ *Cidade:* ${data.city}, ${data.state}
☀️ *Vertical:* ${data.vertical}
💰 *Conta de luz:* R$ ${data.energy_bill || 'N/A'}
📊 *Intent Score:* ${data.intent_score || 0}
🏷️ *Intent Level:* ${data.intent_level || 'cold'}

🔗 *Perfil do lead:* ${data.lead_url || 'N/A'}

_Responda este lead em até ${data.sla_window || '4 horas'}_`.trim(),

    lead_welcome: (data) => `
Olá ${data.lead_first_name || 'tudo bem'}! 👋

Vi que você calculou sua economia solar em ${data.city || 'sua cidade'}.

Posso te ajudar a encontrar as melhores empresas verificadas na sua região?

É rápido e sem compromisso: https://www.avaliasolar.com.br?utm_source=whatsapp&utm_medium=welcome`.trim(),

    follow_up: (data) => `
Olá ${data.lead_first_name || 'tudo bem'}!

Vi que você começou a calcular sua economia solar mas não finalizou.

Posso te ajudar? Me diz qual sua dúvida que eu te mostro o caminho: https://www.avaliasolar.com.br?utm_source=whatsapp&utm_medium=followup`.trim(),

    reactivation: (data) => `
Olá ${data.lead_first_name || 'tudo bem'}!

Faz um tempinho que você visitou o AvaliaSolar. Temos novidades para ${data.city || 'sua cidade'}:

✅ Novas empresas verificadas
✅ Trust Scores atualizados
✅ Reviews recentes de clientes reais

Quer dar uma olhada? https://www.avaliasolar.com.br?utm_source=whatsapp&utm_medium=reactivation`.trim(),

    proposal_sent: (data) => `
Olá ${data.lead_first_name || 'tudo bem'}!

Sua proposta solar está pronta! 🎉

${data.proposal_summary || ''}

Quer conversar sobre os detalhes? Estou à disposição!`.trim()
  };

  const messageType = body.message_type || 'installer_notification';
  const template = templates[messageType] || templates.lead_welcome;
  const messageText = template(body);

  messages.push({
    json: {
      phone: body.phone || body.lead_phone || body.installer_phone,
      message: messageText,
      message_type: messageType,
      lead_id: body.lead_id || body.avails_id,
      company_id: body.company_id,
      session_id: body.session_id,
      sent_at: new Date().toISOString()
    }
  });
}

return messages;

// Log WhatsApp message to database
const items = $input.all();
const logs = [];

for (const item of items) {
  const msg = item.json;

  logs.push({
    json: {
      lead_id: msg.lead_id,
      company_id: msg.company_id,
      direction: 'outbound',
      message_type: msg.message_type,
      phone: msg.phone,
      message_preview: (msg.message || '').substring(0, 200),
      status: item.json.response ? 'sent' : 'failed',
      evolution_response: item.json.response ? JSON.stringify(item.json.response).substring(0, 1000) : null,
      created_at: new Date().toISOString()
    }
  });
}

return logs;
